"""Routes for Run Detail, generated by Dryv; the engine implements ExploreRunDetailService."""

from __future__ import annotations

from abc import ABC, abstractmethod
from collections.abc import Awaitable, Callable
from typing import Annotated

from fastapi import APIRouter, Depends, Path, Request

from mzizi_engine.api.schemas.api.explore.models.job_detail import JobDetail

__all__ = ["ExploreRunDetailService", "build_explore_run_detail_router"]

type Guard = Callable[[Request], Awaitable[None]]
"""An async FastAPI dependency that raises 401 or 403 before the route runs."""


class ExploreRunDetailService(ABC):
    """What Run Detail needs from handwritten code. Raise ``fastapi.HTTPException`` for failures."""

    @abstractmethod
    async def get_job_detail(self, *, job_id: str) -> JobDetail:
        """One job with its event timeline and the folder it wrote."""


def build_explore_run_detail_router(service: ExploreRunDetailService, guard: Guard | None = None) -> APIRouter:
    """Routes for Run Detail, delegating to ``service``; ``guard`` protects every route."""

    router = APIRouter(tags=["Run Detail"], dependencies=[Depends(guard)] if guard else [])

    @router.get(
        "/v1/explore/jobs/{jobId}",
        response_model=JobDetail,
        status_code=200,
        summary="One job with its event timeline and the folder it wrote.",
    )
    async def get_job_detail(
        job_id: Annotated[str, Path(alias="jobId")],
    ) -> JobDetail:
        return await service.get_job_detail(job_id=job_id)

    return router
